var dir = "/home/andr/WORK/GAGG/tmp"

var sig = core.loadNumericArray(dir + "/SensorSignals.txt")
var numEv = sig.length
if (numEv == 0) core.abort("There are no events!")
core.print("Loaded", numEv, "events")

var truePos = core.loadNumericArray(dir + "/PhotonBombs.txt")
if (truePos.length != numEv) core.abort("Failed to load photon bomb positions!")

mercury.newReconstructor("ML", 15)
mercury.setCutoffRadius(40)
mercury.configure_COG(0, 0.99, 0)
mercury.configure_statistical(true, true, 0);

core.print("Staring reconstruction");
var start = core.getTimeMarkMilliseconds()
mercury.reconstructEvents(sig)
var stop = core.getTimeMarkMilliseconds()
core.print("Elapsed time:", stop-start, "ms")

var recPosE = mercury.getRecXYZE()

histName = "h"
hist.new2D(histName, 100, -2, 2,  100, -2, 2)

// Show event position markers
geowin.clearMarkers()
var arRec  = []
var arTrue = []
for (var iEv = 0; iEv < recPosE.length; iEv++)
{
    if (iEv < 1000) arTrue.push(truePos[iEv])

    // Energy = 0 --> reconstruction failed
    if (recPosE[iEv][3] > 0)
    {
        if (iEv < 1000) arRec.push(recPosE[iEv])

        hist.fill(histName, truePos[iEv][2], recPosE[iEv][2], 1)
    }
}
geowin.addMarkers(arTrue, 4, 7, 2)
geowin.addMarkers(arRec,  2, 2, 2)
geowin.showWindow()

// Show reconstruction data
mercury.plot("All", 100, 0,0)
mercury.configure_plotXY_binning(81, -40, 40, 81, -40, 40)
mercury.plot_vsRecXY("All")
mercury.configure_plotXY_truePositions(truePos)
mercury.plot_vsTrueXY("All")

// vs Z

hist.draw(histName, "colz"); grwin.addToBasket("zrecvsztrue")

var fn = "/home/andr/WORK/GAGG/PET/Out1M/ReducedSim" + "/" + "SensorSignals.txt"
var sensSigs = core.loadNumericArray(fn)

hist.new1D("h1", 1000, 0, 0)
hist.new1D("h2", 1000, 0, 0)

var numEv = sensSigs.length
for (var iEv = 0; iEv < numEv; iEv++)
{
    var sensEv = sensSigs[iEv]
    var sum1 = 0
    var sum2 = 0
    for (var iS = 0; iS < 64; iS++)
    {
        sum1 += sensEv[iS]
        sum2 += sensEv[iS+64]
    }
    hist.fill("h1", sum1, 1)
    hist.fill("h2", sum2, 1)
    //if (iEv == 295) core.print(sum1, sum2)
}

hist.draw("h1", "hist")
hist.draw("h2", "histsame")
